package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.FederatedProviderVO;

class FederatedProviderValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of federated provider of user")
  void test_federated_provider_value_holder_assign_plain_value() {
    Object holder = new Object();
    FederatedProviderValueHolder<Object> value = new FederatedProviderValueHolder<>(holder);
    Assertions.assertSame(holder, value.federatedProvider("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getFederatedProviderValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getFederatedProvider().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.federatedProviderNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getFederatedProviderValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getFederatedProvider().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of federated provider of user")
  void test_federated_provider_value_holder_assign_value_object() {
    Object holder = new Object();
    FederatedProviderValueHolder<Object> value = new FederatedProviderValueHolder<>(holder);
    FederatedProviderVO vo = FederatedProviderVO.from("one");
    Assertions.assertFalse(value.getFederatedProviderValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.federatedProvider(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getFederatedProviderValue().orElseThrow());
    Assertions.assertSame(holder, value.federatedProvider(Optional.empty()));
    Assertions.assertFalse(value.getFederatedProviderValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.federatedProvider(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFederatedProviderValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of federated provider of user against the original")
  void test_federated_provider_value_holder_read() {
    Object holder = new Object();
    FederatedProviderValueHolder<Object> value = new FederatedProviderValueHolder<>(holder);
    FederatedProviderVO vo = FederatedProviderVO.from("one");
    FederatedProviderVO other = FederatedProviderVO.from("one");
    User original = Mockito.mock(User.class);
    Mockito.when(original.getFederatedProviderValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFederatedProvider(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readFederatedProvider(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.federatedProvider(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFederatedProvider(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFederatedProvider(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of federated provider of user")
  void test_federated_provider_value_holder_unset() {
    Object holder = new Object();
    FederatedProviderValueHolder<Object> value = new FederatedProviderValueHolder<>(holder);
    FederatedProviderVO vo = FederatedProviderVO.from("one");
    value.federatedProvider(vo);
    Assertions.assertSame(holder, value.unsetFederatedProviderIfMatches("federatedProvider_other"));
    Assertions.assertTrue(value.getFederatedProviderValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetFederatedProviderIfMatches("federatedProvider"));
    Assertions.assertFalse(value.getFederatedProviderValue().isPresent(),
        "The field name must clear the value");
    value.federatedProvider(vo);
    Assertions.assertSame(holder, value.unsetFederatedProvider());
    Assertions.assertFalse(value.getFederatedProviderValue().isPresent(),
        "Unset must clear the value");
  }
}
